import pandas as pd

file_path = '/root/.gemini/tmp/IMF_Commodity_Prices.xlsx'
try:
    df = pd.read_excel(file_path)
    print("Columns:", df.columns.tolist())
    print(df.head())
    # Try to find a row that contains "Gold" to identify the header row if it's not the first one
    for i, row in df.head(20).iterrows():
